'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import {
  Store, Mail, Lock, Eye, EyeOff, Loader2, AlertCircle, ArrowRight,
  TrendingUp, ShieldCheck, Headphones, CheckCircle2, ArrowLeft
} from 'lucide-react';
import { useStore } from '@/store/useStore';

export default function SellerLoginPage() {
  const router = useRouter();
  const login = useStore((s) => s.login);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Please enter your seller email and password.');
      return;
    }
    setError('');
    setLoading(true);

    try {
      // Clear old session credentials first to prevent cross-account contamination
      if (typeof window !== 'undefined') {
        localStorage.removeItem('zibonbaba_token');
        localStorage.removeItem('zibonbaba_user');
        localStorage.removeItem('zibonbaba_role');
        sessionStorage.clear();
      }

      const success = await login(email, password);
      if (success) {
        let userRole = '';
        if (typeof window !== 'undefined') {
          const uStr = localStorage.getItem('zibonbaba_user');
          if (uStr) {
            try { userRole = JSON.parse(uStr).role; } catch (_) {}
          }
        }
        const normalized = userRole ? userRole.toUpperCase() : '';
        if (['CUSTOMER'].includes(normalized)) {
          setError('This account is registered as a Customer. Please sign in with a Seller account or register your store.');
          useStore.getState().logout();
          return;
        }

        router.push('/seller');
      } else {
        setError('Invalid seller credentials. Please verify your email and password.');
      }
    } catch {
      setError('Something went wrong. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-950 text-white flex flex-col justify-between relative overflow-hidden">
      {/* Top Header */}
      <header className="border-b border-white/10 bg-gray-900/50 backdrop-blur-md px-6 py-4 flex items-center justify-between z-20">
        <div className="flex items-center gap-3">
          <Link href="/" className="flex items-center gap-2 group">
            <div className="w-9 h-9 rounded-xl bg-primary flex items-center justify-center font-black text-gray-900 text-lg shadow-glow">
              Z
            </div>
            <span className="font-extrabold text-xl tracking-tight text-white">
              Zibon<span className="text-primary">baba</span>
            </span>
          </Link>
          <span className="text-xs px-2.5 py-1 rounded-full bg-primary/10 border border-primary/30 text-primary font-bold tracking-wide uppercase">
            Seller Center
          </span>
        </div>
        <div className="flex items-center gap-4 text-xs">
          <Link href="/" className="text-gray-400 hover:text-white transition-colors flex items-center gap-1.5">
            <ArrowLeft size={14} /> Back to Marketplace
          </Link>
          <Link href="/seller/register" className="hidden sm:inline-flex items-center gap-1 bg-primary/10 hover:bg-primary/20 text-primary border border-primary/30 font-bold px-3.5 py-1.5 rounded-lg transition-all">
            Open Store <ArrowRight size={14} />
          </Link>
        </div>
      </header>

      {/* Center Main */}
      <div className="flex-1 flex items-center justify-center px-4 py-12 relative z-10">
        {/* Background Glowing Gradients */}
        <div className="absolute top-1/4 left-1/4 w-[450px] h-[450px] rounded-full bg-primary/10 blur-[120px] pointer-events-none" />
        <div className="absolute bottom-1/4 right-1/4 w-[400px] h-[400px] rounded-full bg-amber-500/10 blur-[120px] pointer-events-none" />

        <div className="w-full max-w-4xl grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
          {/* Left Hero Benefits */}
          <div className="hidden md:flex flex-col space-y-6 pr-4">
            <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/5 border border-white/10 text-xs text-yellow-400 w-fit">
              <TrendingUp size={14} /> Accelerate Your E-Commerce Growth
            </div>
            <h1 className="text-3xl lg:text-4xl font-black text-white leading-tight">
              Manage your products, orders & payouts in one powerful hub.
            </h1>
            <p className="text-gray-400 text-sm leading-relaxed">
              Join thousands of merchants growing their business with Zibonbaba Seller Center. Enjoy dedicated order logistics, guaranteed payouts, and real-time inventory management.
            </p>

            <div className="space-y-3 pt-2">
              <div className="flex items-center gap-3 text-sm text-gray-300">
                <div className="w-6 h-6 rounded-full bg-green-500/20 text-green-400 flex items-center justify-center shrink-0">
                  <CheckCircle2 size={14} />
                </div>
                <span>Fast onboarding & store approval</span>
              </div>
              <div className="flex items-center gap-3 text-sm text-gray-300">
                <div className="w-6 h-6 rounded-full bg-green-500/20 text-green-400 flex items-center justify-center shrink-0">
                  <CheckCircle2 size={14} />
                </div>
                <span>Competitive platform commission rates</span>
              </div>
              <div className="flex items-center gap-3 text-sm text-gray-300">
                <div className="w-6 h-6 rounded-full bg-green-500/20 text-green-400 flex items-center justify-center shrink-0">
                  <CheckCircle2 size={14} />
                </div>
                <span>Direct bank & mobile wallet settlement</span>
              </div>
            </div>
          </div>

          {/* Right Login Card */}
          <div className="backdrop-blur-xl bg-white/5 border border-white/10 rounded-2xl p-6 sm:p-8 shadow-2xl">
            <div className="mb-6">
              <div className="w-12 h-12 rounded-xl bg-primary/20 border border-primary/40 flex items-center justify-center text-primary mb-3">
                <Store size={24} />
              </div>
              <h2 className="text-xl font-bold text-white">Sign in to Seller Center</h2>
              <p className="text-xs text-gray-400 mt-1">Enter your merchant credentials to access your dashboard</p>
            </div>

            {error && (
              <div className="flex items-start gap-2.5 bg-red-500/10 border border-red-500/30 text-red-400 rounded-lg p-3 mb-5 text-xs">
                <AlertCircle size={16} className="shrink-0 mt-0.5" />
                <span>{error}</span>
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-gray-300 mb-1.5">
                  Business Email or Phone
                </label>
                <div className="relative">
                  <Mail size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input
                    type="text"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="vendor@zibonbaba.com"
                    required
                    className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-lg pl-10 pr-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-300 mb-1.5">
                  Password
                </label>
                <div className="relative">
                  <Lock size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="••••••••"
                    required
                    className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-lg pl-10 pr-10 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-300 p-1"
                    tabIndex={-1}
                  >
                    {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                  </button>
                </div>
              </div>

              <div className="flex items-center justify-between text-xs pt-1">
                <label className="flex items-center gap-2 cursor-pointer text-gray-400">
                  <input
                    type="checkbox"
                    checked={rememberMe}
                    onChange={(e) => setRememberMe(e.target.checked)}
                    className="rounded bg-white/5 border-white/20 text-primary focus:ring-0 w-3.5 h-3.5"
                  />
                  <span>Remember session</span>
                </label>
                <Link href="/seller/forgot-password" className="text-yellow-400 hover:text-yellow-300 font-medium transition-colors">
                  Forgot Password?
                </Link>
              </div>

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-primary hover:bg-primary-accent text-gray-950 font-extrabold py-3 rounded-lg transition-all shadow-glow hover:shadow-[0_0_25px_rgba(255,193,7,0.4)] disabled:opacity-60 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-sm mt-2"
              >
                {loading ? (
                  <>
                    <Loader2 size={16} className="animate-spin" />
                    <span>Verifying Seller Account...</span>
                  </>
                ) : (
                  <>
                    <span>Sign In to Seller Center</span>
                    <ArrowRight size={16} />
                  </>
                )}
              </button>
            </form>

            <div className="mt-6 pt-5 border-t border-white/10 text-center">
              <p className="text-xs text-gray-400">
                New to Zibonbaba?{' '}
                <Link href="/seller/register" className="text-primary hover:text-yellow-300 font-bold transition-colors">
                  Register as a Seller
                </Link>
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Footer */}
      <footer className="border-t border-white/10 bg-gray-950 py-4 px-6 text-center text-xs text-gray-500 z-10">
        <p>© {new Date().getFullYear()} Zibonbaba Seller Center. All Rights Reserved. Dedicated Merchant Portal.</p>
      </footer>
    </div>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import {
  User, Mail, Phone, Lock, Eye, EyeOff,
  Loader2, AlertCircle, CheckCircle2, Tag, ArrowRight, ArrowLeft,
  ShoppingBag, Store, Briefcase
} from 'lucide-react';
import { useStore } from '@/store/useStore';

const BUSINESS_CATEGORIES = [
  'Electronics & Gadgets',
  'Fashion & Apparel',
  'Health & Beauty',
  'Home & Kitchen',
  'Groceries & Food',
  'Books & Stationery',
  'Toys & Kids',
  'Sports & Fitness',
  'Automotive & Motor Accessories',
  'Jewelry & Luxury Watches',
  'General Retail'
];

interface FieldProps {
  id: string;
  label: string;
  type?: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  icon: React.ReactNode;
  required?: boolean;
}

function Field({ id, label, type = 'text', value, onChange, placeholder, icon, required = true }: FieldProps) {
  const [show, setShow] = useState(false);
  const isPassword = type === 'password';
  return (
    <div>
      <label htmlFor={id} className="block text-xs font-semibold text-gray-300 mb-1.5">
        {label}{!required && <span className="text-gray-500 text-xs ml-1">(optional)</span>}
      </label>
      <div className="relative">
        <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-500">{icon}</span>
        <input
          id={id}
          type={isPassword ? (show ? 'text' : 'password') : type}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          required={required}
          className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-xl pl-10 pr-10 py-3 text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
        />
        {isPassword && (
          <button
            type="button"
            onClick={() => setShow(!show)}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-300 transition-colors p-1"
            tabIndex={-1}
            aria-label={show ? 'Hide password' : 'Show password'}
          >
            {show ? <EyeOff size={16} /> : <Eye size={16} />}
          </button>
        )}
      </div>
    </div>
  );
}

export default function SellerRegisterPage() {
  const router = useRouter();

  // Default to 'seller' tab on /seller/register
  const [accountType, setAccountType] = useState<'customer' | 'seller'>('seller');

  // Form States
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [storeName, setStoreName] = useState('');
  const [businessCategory, setBusinessCategory] = useState('Electronics & Gadgets');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [referralCode, setReferralCode] = useState('');
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!fullName.trim()) {
      setError('Please enter your full name.');
      return;
    }
    if (!email.trim() || !email.includes('@')) {
      setError('Please enter a valid email address.');
      return;
    }
    if (accountType === 'seller' && !storeName.trim()) {
      setError('Please enter your Store / Business name.');
      return;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match.');
      return;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }
    if (!termsAccepted) {
      setError('Please accept the Terms of Service and Privacy Policy to continue.');
      return;
    }

    setLoading(true);

    try {
      // Clear old session credentials first to guarantee clean account isolation
      if (typeof window !== 'undefined') {
        localStorage.removeItem('zibonbaba_token');
        localStorage.removeItem('zibonbaba_user');
        localStorage.removeItem('zibonbaba_role');
        sessionStorage.clear();
      }

      const body: Record<string, any> = {
        fullName: fullName.trim(),
        email: email.trim().toLowerCase(),
        phone: phone.trim() || undefined,
        password,
        role: accountType === 'seller' ? 'VENDOR_ADMIN' : 'CUSTOMER',
      };

      if (accountType === 'seller') {
        body.storeName = storeName.trim();
        body.businessType = businessCategory;
      } else if (referralCode.trim()) {
        body.referralCode = referralCode.trim();
      }

      const res = await fetch('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      const data = await res.json();
      if (!res.ok) {
        setError(data.error || data.message || 'Registration failed. Please try again.');
        return;
      }

      // Establish fresh isolated session
      if (data.accessToken && typeof window !== 'undefined') {
        localStorage.setItem('zibonbaba_token', data.accessToken);
        localStorage.setItem('zibonbaba_user', JSON.stringify(data.user));
        localStorage.setItem('zibonbaba_role', data.user.role);
        document.cookie = `zibonbaba_token=${data.accessToken}; path=/; max-age=604800; SameSite=Lax`;
        document.cookie = `zibonbaba_role=${data.user.role}; path=/; max-age=604800; SameSite=Lax`;
        document.cookie = `zibonbaba_user=${encodeURIComponent(JSON.stringify(data.user))}; path=/; max-age=604800; SameSite=Lax`;

        useStore.setState({
          isLoggedIn: true,
          token: data.accessToken,
          role: accountType === 'seller' ? 'vendor' : 'customer',
          username: data.user?.fullName || data.user?.email || 'User',
          userEmail: data.user?.email || '',
          cart: [],
          orders: []
        });
      }

      setSuccess(true);
    } catch {
      setError('Could not connect to the server. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950 text-white relative overflow-hidden px-4">
        <Link
          href="/"
          className="absolute top-4 left-4 z-50 p-2.5 rounded-full bg-white/5 hover:bg-white/10 text-gray-400 hover:text-white transition-colors border border-white/10 backdrop-blur-sm"
        >
          <ArrowLeft size={20} />
        </Link>

        <div className="absolute inset-0 bg-gradient-to-br from-gray-900 via-gray-950 to-gray-900" />
        <div className="absolute top-1/3 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] rounded-full bg-primary/10 blur-[130px] pointer-events-none" />

        <div className="relative z-10 w-full max-w-md text-center backdrop-blur-xl bg-white/5 border border-white/10 rounded-3xl p-8 sm:p-10 shadow-2xl">
          <div className="w-16 h-16 sm:w-20 sm:h-20 bg-green-500/20 border border-green-500/30 rounded-2xl flex items-center justify-center mx-auto mb-5 text-green-400 shadow-glow">
            {accountType === 'seller' ? <Store size={36} /> : <CheckCircle2 size={36} />}
          </div>
          <h2 className="text-xl sm:text-2xl font-black text-white mb-2">
            {accountType === 'seller' ? 'Store Application Submitted! 🏪' : 'Welcome to Zibonbaba! 🎉'}
          </h2>
          <p className="text-gray-400 text-xs sm:text-sm mb-6 leading-relaxed">
            {accountType === 'seller'
              ? `Your store application for "${storeName}" is registered. You can now access your Seller Center to configure inventory and view your store.`
              : 'Your customer account has been created with 100 welcome bonus loyalty points. Start shopping today!'}
          </p>

          <div className="flex flex-col gap-3">
            <Link
              href={accountType === 'seller' ? '/seller' : '/'}
              className="w-full inline-flex items-center justify-center gap-2 bg-primary hover:bg-primary-accent text-gray-950 font-black px-6 py-3.5 rounded-xl transition-all shadow-glow text-sm"
            >
              {accountType === 'seller' ? 'Open Seller Center' : 'Start Shopping'} <ArrowRight size={16} />
            </Link>
            <Link
              href={accountType === 'seller' ? '/seller/login' : '/login'}
              className="w-full inline-flex items-center justify-center gap-2 bg-white/5 hover:bg-white/10 border border-white/10 text-gray-300 font-bold px-6 py-3 rounded-xl transition-all text-sm"
            >
              Sign In
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden bg-gray-950 text-white py-10 px-4 sm:px-6">
      {/* Back Button */}
      <Link
        href="/"
        className="absolute top-4 left-4 z-50 p-2.5 rounded-full bg-white/5 hover:bg-white/10 text-gray-400 hover:text-white transition-colors border border-white/10 backdrop-blur-sm"
        aria-label="Back to Home"
      >
        <ArrowLeft size={20} />
      </Link>

      {/* Background Gradients */}
      <div className="absolute inset-0 z-0">
        <div className="absolute inset-0 bg-gradient-to-br from-gray-900 via-gray-950 to-gray-900" />
        <div className="absolute top-1/4 left-1/4 w-[450px] h-[450px] rounded-full bg-primary/10 blur-[130px] pointer-events-none" />
        <div className="absolute bottom-1/4 right-1/4 w-[450px] h-[450px] rounded-full bg-amber-500/10 blur-[130px] pointer-events-none" />
      </div>

      <div className="relative z-10 w-full max-w-lg">
        {/* Branding & Header */}
        <div className="text-center mb-6">
          <Link href="/" className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-primary shadow-glow mb-3">
            <span className="text-2xl font-black text-gray-950">Z</span>
          </Link>
          <h1 className="text-2xl sm:text-3xl font-black text-primary tracking-tight">Zibonbaba</h1>
          <p className="text-gray-400 text-xs sm:text-sm mt-1">
            Create your account to start shopping or selling
          </p>
        </div>

        {/* Card Container */}
        <div className="backdrop-blur-xl bg-white/5 border border-white/10 rounded-3xl shadow-2xl p-6 sm:p-8 space-y-6">
          {/* Top Account Type Pill Switcher */}
          <div className="bg-gray-900/80 border border-white/10 p-1.5 rounded-2xl flex gap-2">
            <button
              type="button"
              onClick={() => {
                setAccountType('customer');
                setError('');
              }}
              className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs sm:text-sm font-bold transition-all ${
                accountType === 'customer'
                  ? 'bg-primary text-gray-950 font-black shadow-glow'
                  : 'text-gray-400 hover:text-white hover:bg-white/5'
              }`}
            >
              <ShoppingBag size={16} />
              <span>Customer</span>
            </button>
            <button
              type="button"
              onClick={() => {
                setAccountType('seller');
                setError('');
              }}
              className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs sm:text-sm font-bold transition-all ${
                accountType === 'seller'
                  ? 'bg-primary text-gray-950 font-black shadow-glow'
                  : 'text-gray-400 hover:text-white hover:bg-white/5'
              }`}
            >
              <Store size={16} />
              <span>Seller / Merchant</span>
            </button>
          </div>

          {/* Error Message */}
          {error && (
            <div className="flex items-center gap-2.5 bg-red-500/10 border border-red-500/30 text-red-400 rounded-xl p-3 text-xs sm:text-sm">
              <AlertCircle size={16} className="shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <Field
              id="seller-fullname"
              label="Full Name"
              value={fullName}
              onChange={setFullName}
              placeholder="e.g. John Doe"
              icon={<User size={16} />}
            />

            <Field
              id="seller-email"
              label="Email Address"
              type="email"
              value={email}
              onChange={setEmail}
              placeholder="you@example.com"
              icon={<Mail size={16} />}
            />

            <Field
              id="seller-phone"
              label="Phone Number"
              type="tel"
              value={phone}
              onChange={setPhone}
              placeholder="+880 1XXX-XXXXXX"
              icon={<Phone size={16} />}
              required={false}
            />

            {/* Seller Specific Fields */}
            {accountType === 'seller' && (
              <>
                <Field
                  id="seller-storename"
                  label="Store / Business Name"
                  value={storeName}
                  onChange={setStoreName}
                  placeholder="e.g. Dhaka Electronics Mart"
                  icon={<Store size={16} />}
                  required={true}
                />

                <div>
                  <label htmlFor="seller-category" className="block text-xs font-semibold text-gray-300 mb-1.5">
                    Business Category
                  </label>
                  <div className="relative">
                    <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-500">
                      <Briefcase size={16} />
                    </span>
                    <select
                      id="seller-category"
                      value={businessCategory}
                      onChange={(e) => setBusinessCategory(e.target.value)}
                      className="w-full bg-gray-900 border border-white/10 text-white rounded-xl pl-10 pr-4 py-3 text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all appearance-none cursor-pointer"
                    >
                      {BUSINESS_CATEGORIES.map((cat) => (
                        <option key={cat} value={cat}>{cat}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </>
            )}

            {/* Customer Referral Code Field */}
            {accountType === 'customer' && (
              <Field
                id="seller-referral"
                label="Referral Code"
                value={referralCode}
                onChange={setReferralCode}
                placeholder="e.g. ZB8X9K2"
                icon={<Tag size={16} />}
                required={false}
              />
            )}

            <Field
              id="seller-password"
              label="Password"
              type="password"
              value={password}
              onChange={setPassword}
              placeholder="Min. 6 characters"
              icon={<Lock size={16} />}
            />

            <Field
              id="seller-confirm-password"
              label="Confirm Password"
              type="password"
              value={confirmPassword}
              onChange={setConfirmPassword}
              placeholder="Re-enter your password"
              icon={<Lock size={16} />}
            />

            {/* Terms Checkbox */}
            <div className="pt-1">
              <label htmlFor="seller-terms-checkbox" className="flex items-start gap-2.5 cursor-pointer group">
                <div className="relative mt-0.5 shrink-0">
                  <input
                    id="seller-terms-checkbox"
                    type="checkbox"
                    checked={termsAccepted}
                    onChange={(e) => setTermsAccepted(e.target.checked)}
                    className="sr-only peer"
                  />
                  <div className="w-4 h-4 border border-white/20 rounded bg-white/5 peer-checked:bg-primary peer-checked:border-primary transition-all flex items-center justify-center">
                    {termsAccepted && <CheckCircle2 size={11} className="text-gray-950" />}
                  </div>
                </div>
                <span className="text-xs text-gray-400 leading-relaxed select-none">
                  I agree to the{' '}
                  <span className="text-primary font-bold hover:underline cursor-pointer">Terms of Service</span>
                  {' '}and{' '}
                  <span className="text-primary font-bold hover:underline cursor-pointer">Privacy Policy</span>
                </span>
              </label>
            </div>

            {/* Submit Button */}
            <button
              id="seller-register-submit-btn"
              type="submit"
              disabled={loading}
              className="w-full bg-primary hover:bg-primary-accent text-gray-950 font-black py-3.5 rounded-xl transition-all shadow-glow hover:shadow-[0_0_25px_rgba(255,193,7,0.4)] disabled:opacity-60 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-sm sm:text-base mt-2"
            >
              {loading ? (
                <>
                  <Loader2 size={18} className="animate-spin" />
                  <span>{accountType === 'seller' ? 'Creating Seller Store...' : 'Creating Account...'}</span>
                </>
              ) : (
                <>
                  <span>{accountType === 'seller' ? 'Create Seller Store' : 'Create Customer Account'}</span>
                  <ArrowRight size={16} />
                </>
              )}
            </button>
          </form>

          {/* Login Link */}
          <p className="text-center text-xs sm:text-sm text-gray-400 pt-2 border-t border-white/10">
            Already have an account?{' '}
            <Link
              href={accountType === 'seller' ? '/seller/login' : '/login'}
              className="text-primary hover:text-yellow-300 font-bold transition-colors"
            >
              Sign In
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  TrendingUp, Package, ShoppingBag, DollarSign, AlertTriangle, RefreshCw, X, Lock, ShieldAlert,
  Trash2, Edit, Clock, Wallet, Bell, Sparkles, Check, LogOut, Plus, ExternalLink, ArrowRight, Store, Users
} from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useStore } from '@/store/useStore';

type SellerTab = 'analytics' | 'products' | 'orders' | 'wallet' | 'staff' | 'settings';

interface SellerProduct {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  categoryId?: string;
  sku: string;
  stock: number;
  status: string;
  createdAt: string;
}

interface SellerOrder {
  id: string;
  date: string;
  customerName: string;
  customerPhone?: string;
  subTotal: number;
  total: number;
  platformFee: number;
  sellerPayout: number;
  status: string;
  source: string;
  items: {
    product: {
      id: string;
      name: string;
      price: number;
      sku: string;
    };
    quantity: number;
  }[];
}

interface StoreInfo {
  id: string;
  name: string;
  description?: string;
  logo?: string;
  banner?: string;
  isApproved: boolean;
  commissionRate: number;
  createdAt?: string;
}

export default function SellerPortalPage() {
  const router = useRouter();
  const { isLoggedIn, role, logout } = useStore();
  const [activeTab, setActiveTab] = useState<SellerTab>('analytics');
  const [isMounted, setIsMounted] = useState(false);
  const [loading, setLoading] = useState(true);

  // Isolated Seller States (Strictly scoped to authenticated store)
  const [sellerProducts, setSellerProducts] = useState<SellerProduct[]>([]);
  const [sellerOrders, setSellerOrders] = useState<SellerOrder[]>([]);
  const [storeInfo, setStoreInfo] = useState<StoreInfo | null>(null);
  const [earnings, setEarnings] = useState(0);
  const [totalGrossSales, setTotalGrossSales] = useState(0);
  const [withdraws, setWithdraws] = useState<{ id: string; amount: number; status: string; date: string }[]>([]);
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [monthlyGMV, setMonthlyGMV] = useState<{ month: string; value: number }[]>([]);
  const [totalCustomers, setTotalCustomers] = useState(0);
  const [staffList, setStaffList] = useState<{ id: string; name: string; role: string; status: string; permissions: string }[]>([]);

  // Add Product Form State
  const [newProdName, setNewProdName] = useState('');
  const [newProdPrice, setNewProdPrice] = useState('');
  const [newProdSKU, setNewProdSKU] = useState('');
  const [newProdStock, setNewProdStock] = useState('20');
  const [newProdCategory, setNewProdCategory] = useState('Electronics & Gadgets');
  const [newProdDesc, setNewProdDesc] = useState('');
  const [isSubmittingProd, setIsSubmittingProd] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');
  const [errorMsg, setErrorMsg] = useState('');

  // Edit Product Modal State
  const [editingProduct, setEditingProduct] = useState<SellerProduct | null>(null);
  const [editName, setEditName] = useState('');
  const [editPrice, setEditPrice] = useState('');
  const [editStock, setEditStock] = useState('');
  const [editDesc, setEditDesc] = useState('');

  // Store Settings Form State
  const [storeNameInput, setStoreNameInput] = useState('');
  const [storeDescInput, setStoreDescInput] = useState('');

  // Staff Form State
  const [newStaffName, setNewStaffName] = useState('');
  const [newStaffRole, setNewStaffRole] = useState('Sales Staff');
  const [newStaffEmail, setNewStaffEmail] = useState('');

  const getAuthToken = () => {
    return typeof window !== 'undefined' ? localStorage.getItem('zibonbaba_token') : null;
  };

  // 1. Fetch Store Profile
  const fetchStoreProfile = useCallback(async () => {
    const token = getAuthToken();
    if (!token) return;
    try {
      const res = await fetch('/api/seller/store', { headers: { Authorization: `Bearer ${token}` } });
      const data = await res.json();
      if (res.ok && data.store) {
        setStoreInfo(data.store);
        setStoreNameInput(data.store.name || '');
        setStoreDescInput(data.store.description || '');
      }
    } catch (_) {}
  }, []);

  // 2. Fetch Isolated Products
  const fetchSellerProducts = useCallback(async () => {
    const token = getAuthToken();
    if (!token) return;
    try {
      const res = await fetch('/api/seller/products', { headers: { Authorization: `Bearer ${token}` } });
      const data = await res.json();
      if (res.ok && Array.isArray(data.products)) {
        setSellerProducts(data.products);
      }
    } catch (_) {}
  }, []);

  // 3. Fetch Isolated Orders
  const fetchSellerOrders = useCallback(async () => {
    const token = getAuthToken();
    if (!token) return;
    try {
      const res = await fetch('/api/seller/orders', { headers: { Authorization: `Bearer ${token}` } });
      const data = await res.json();
      if (res.ok && Array.isArray(data.orders)) {
        setSellerOrders(data.orders);
      }
    } catch (_) {}
  }, []);

  // 4. Fetch Isolated Wallet & Withdrawals
  const fetchSellerWallet = useCallback(async () => {
    const token = getAuthToken();
    if (!token) return;
    try {
      const res = await fetch('/api/seller/wallet', { headers: { Authorization: `Bearer ${token}` } });
      const data = await res.json();
      if (res.ok) {
        if (data.earnings !== undefined) setEarnings(data.earnings);
        if (data.grossSales !== undefined) setTotalGrossSales(data.grossSales);
        if (Array.isArray(data.withdrawals)) setWithdraws(data.withdrawals);
      }
    } catch (_) {}
  }, []);

  // 5. Fetch Isolated Analytics
  const fetchSellerAnalytics = useCallback(async () => {
    const token = getAuthToken();
    if (!token) return;
    try {
      const res = await fetch('/api/seller/analytics', { headers: { Authorization: `Bearer ${token}` } });
      const data = await res.json();
      if (res.ok) {
        if (Array.isArray(data.monthlyGMV)) setMonthlyGMV(data.monthlyGMV);
        if (data.totalCustomers !== undefined) setTotalCustomers(data.totalCustomers);
      }
    } catch (_) {}
  }, []);

  // 6. Fetch Staff Members
  const fetchSellerStaff = useCallback(async () => {
    const token = getAuthToken();
    if (!token) return;
    try {
      const res = await fetch('/api/seller/staff', { headers: { Authorization: `Bearer ${token}` } });
      const data = await res.json();
      if (res.ok && Array.isArray(data.staff)) {
        setStaffList(data.staff.map((s: any) => ({
          id: s.id,
          name: s.user?.profile?.fullName || s.user?.email || 'Staff Member',
          role: s.jobTitle || 'Staff',
          status: s.isActive ? 'ACTIVE' : 'INACTIVE',
          permissions: typeof s.permissions === 'string' ? JSON.parse(s.permissions).join(', ') : 'Inventory, Products'
        })));
      }
    } catch (_) {}
  }, []);

  // Initial Load
  useEffect(() => {
    setIsMounted(true);
    const token = getAuthToken();
    if (token) {
      setLoading(true);
      Promise.all([
        fetchStoreProfile(),
        fetchSellerProducts(),
        fetchSellerOrders(),
        fetchSellerWallet(),
        fetchSellerAnalytics(),
        fetchSellerStaff()
      ]).finally(() => setLoading(false));
    }
  }, [fetchStoreProfile, fetchSellerProducts, fetchSellerOrders, fetchSellerWallet, fetchSellerAnalytics, fetchSellerStaff]);

  if (!isMounted) return null;

  // Strict Role & Auth Guard
  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
        <div className="bg-slate-900 border border-white/10 rounded-3xl p-8 max-w-sm w-full text-center text-white">
          <div className="w-16 h-16 bg-red-500/10 rounded-2xl flex items-center justify-center text-red-500 mx-auto mb-6 border border-red-500/20">
            <Lock className="w-8 h-8" />
          </div>
          <h1 className="text-xl font-black mb-2">Seller Login Required</h1>
          <p className="text-xs text-slate-400 mb-6">Please log in to your Seller Center account to access your store portal.</p>
          <Link href="/seller/login" className="bg-primary text-gray-950 font-black text-xs px-6 py-3 rounded-2xl block w-full text-center shadow-glow hover:bg-primary-accent transition-all">
            Proceed to Seller Login
          </Link>
        </div>
      </div>
    );
  }

  const normalizedRole = (role || '').trim().toLowerCase();
  const allowedRoles = ['vendor', 'staff', 'vendor_admin', 'vendor_staff', 'seller', 'superadmin', 'admin'];
  if (!allowedRoles.includes(normalizedRole)) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
        <div className="bg-slate-900 border border-white/10 rounded-3xl p-8 max-w-sm w-full text-center text-white">
          <div className="w-16 h-16 bg-rose-500/10 rounded-2xl flex items-center justify-center text-rose-500 mx-auto mb-6 border border-rose-500/20">
            <ShieldAlert className="w-8 h-8" />
          </div>
          <h1 className="text-xl font-black mb-2">Access Restricted</h1>
          <p className="text-xs text-slate-400 mb-6">You are signed in with a Customer account. Please register your store or log in with a Seller account.</p>
          <div className="space-y-2">
            <Link href="/seller/register" className="bg-primary text-gray-950 font-black text-xs px-6 py-3 rounded-2xl block w-full text-center">
              Register as Seller
            </Link>
            <button onClick={() => router.push('/')} className="bg-white/5 border border-white/10 text-slate-300 font-bold text-xs px-6 py-3 rounded-2xl block w-full">
              Back to Marketplace
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Handle Add Product
  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProdName.trim() || !newProdPrice.trim()) {
      setErrorMsg('Product name and price are required.');
      return;
    }
    const token = getAuthToken();
    if (!token) return;

    setIsSubmittingProd(true);
    setErrorMsg('');
    try {
      const res = await fetch('/api/seller/products', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          name: newProdName.trim(),
          price: parseFloat(newProdPrice),
          category: newProdCategory,
          sku: newProdSKU.trim() || undefined,
          stock: parseInt(newProdStock, 10) || 20,
          description: newProdDesc.trim() || undefined
        })
      });
      const data = await res.json();
      if (!res.ok) {
        setErrorMsg(data.error || 'Failed to add product.');
        return;
      }

      setNewProdName('');
      setNewProdPrice('');
      setNewProdSKU('');
      setNewProdDesc('');
      setSuccessMsg('Product SKU registered successfully in your store catalog!');
      setTimeout(() => setSuccessMsg(''), 4000);
      await fetchSellerProducts();
    } catch {
      setErrorMsg('Failed to connect to server. Please try again.');
    } finally {
      setIsSubmittingProd(false);
    }
  };

  // Handle Open Edit Product Modal
  const handleOpenEditProduct = (prod: SellerProduct) => {
    setEditingProduct(prod);
    setEditName(prod.name);
    setEditPrice(prod.price.toString());
    setEditStock(prod.stock.toString());
    setEditDesc(prod.description || '');
  };

  // Handle Save Edit Product
  const handleSaveEditProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    const token = getAuthToken();
    if (!token) return;

    try {
      const res = await fetch(`/api/seller/products/${editingProduct.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          name: editName.trim(),
          price: parseFloat(editPrice),
          stock: parseInt(editStock, 10),
          description: editDesc.trim()
        })
      });
      if (res.ok) {
        setEditingProduct(null);
        setSuccessMsg('Product SKU updated successfully!');
        setTimeout(() => setSuccessMsg(''), 3500);
        await fetchSellerProducts();
      } else {
        const data = await res.json();
        alert(data.error || 'Failed to update product.');
      }
    } catch (_) {
      alert('Network error while updating product.');
    }
  };

  // Handle Delete Product
  const handleDeleteProductItem = async (prodId: string) => {
    if (!confirm('Are you sure you want to delete this product listing?')) return;
    const token = getAuthToken();
    if (!token) return;

    try {
      const res = await fetch(`/api/seller/products/${prodId}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` }
      });
      if (res.ok) {
        setSuccessMsg('Product listing removed.');
        setTimeout(() => setSuccessMsg(''), 3500);
        await fetchSellerProducts();
      } else {
        const data = await res.json();
        alert(data.error || 'Failed to delete product.');
      }
    } catch (_) {
      alert('Network error while deleting product.');
    }
  };

  // Handle Order Status Change
  const handleStatusChange = async (orderId: string, newStatus: string) => {
    const token = getAuthToken();
    if (!token) return;

    try {
      const res = await fetch('/api/seller/orders', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ orderId, status: newStatus })
      });
      if (res.ok) {
        setSuccessMsg(`Order ${orderId} updated to ${newStatus}`);
        setTimeout(() => setSuccessMsg(''), 3500);
        await fetchSellerOrders();
      } else {
        const data = await res.json();
        alert(data.error || 'Failed to update order status.');
      }
    } catch (_) {}
  };

  // Handle Payout Withdrawal Request
  const handleRequestWithdraw = async (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(withdrawAmount);
    if (!amount || amount <= 0 || amount > earnings) {
      alert('Please enter a valid payout amount within your available balance.');
      return;
    }
    const token = getAuthToken();
    if (!token) return;

    try {
      const res = await fetch('/api/seller/wallet', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ amount, bankDetails: 'Primary Bank Account', payoutMethod: 'BANK_TRANSFER' })
      });
      const data = await res.json();
      if (res.ok) {
        setWithdrawAmount('');
        alert('Withdrawal payout request submitted for review!');
        await fetchSellerWallet();
      } else {
        alert(data.error || 'Failed to request payout.');
      }
    } catch (_) {
      alert('Network error during payout request.');
    }
  };

  // Handle Save Store Settings
  const handleSaveStoreSettings = async (e: React.FormEvent) => {
    e.preventDefault();
    const token = getAuthToken();
    if (!token) return;

    try {
      const res = await fetch('/api/seller/store', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ name: storeNameInput.trim(), description: storeDescInput.trim() })
      });
      if (res.ok) {
        alert('Store profile updated successfully!');
        await fetchStoreProfile();
      } else {
        const data = await res.json();
        alert(data.error || 'Failed to update store settings.');
      }
    } catch (_) {
      alert('Network error while saving settings.');
    }
  };

  // Handle Add Staff
  const handleAddStaff = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStaffName.trim() || !newStaffEmail.trim()) return;
    const token = getAuthToken();
    if (!token) return;

    try {
      const res = await fetch('/api/seller/staff', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          email: newStaffEmail.trim(),
          fullName: newStaffName.trim(),
          jobTitle: newStaffRole,
          permissions: ['view:products', 'view:orders', 'view:inventory']
        })
      });
      if (res.ok) {
        alert('Staff member invitation created.');
        setNewStaffName('');
        setNewStaffEmail('');
        await fetchSellerStaff();
      } else {
        const data = await res.json();
        alert(data.error || 'Failed to add staff member.');
      }
    } catch (_) {}
  };

  const lowStockItems = sellerProducts.filter(p => p.stock <= 10);

  return (
    <div className="min-h-screen bg-gray-950 text-slate-100 flex flex-col md:flex-row antialiased">
      {/* SIDEBAR NAVIGATION */}
      <aside className="w-full md:w-64 bg-gray-900 border-r border-white/10 p-5 flex flex-col justify-between shrink-0">
        <div className="space-y-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-primary flex items-center justify-center font-black text-gray-950 text-xl shadow-glow">
              Z
            </div>
            <div>
              <h2 className="font-black text-white text-base tracking-tight leading-none">
                Zibon<span className="text-primary">baba</span>
              </h2>
              <span className="text-[10px] text-yellow-400 font-bold uppercase tracking-wider block mt-1">
                Seller Center
              </span>
            </div>
          </div>

          {/* Store Info Mini Badge */}
          <div className="bg-white/5 border border-white/10 rounded-xl p-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] text-slate-400 font-bold uppercase">Active Store</span>
              <span className={`text-[9px] font-black px-1.5 py-0.5 rounded ${storeInfo?.isApproved ? 'bg-emerald-500/20 text-emerald-400' : 'bg-yellow-500/20 text-yellow-400'}`}>
                {storeInfo?.isApproved ? 'VERIFIED' : 'PENDING'}
              </span>
            </div>
            <p className="text-xs font-bold text-white mt-1 truncate">{storeInfo?.name || 'My Seller Store'}</p>
            {storeInfo?.id && (
              <Link
                href={`/store/${storeInfo.id}`}
                target="_blank"
                className="text-[10px] text-primary hover:underline flex items-center gap-1 mt-1 font-semibold"
              >
                View Public Store <ExternalLink size={10} />
              </Link>
            )}
          </div>

          {/* Navigation Links */}
          <nav className="space-y-1 text-xs font-bold">
            {[
              { id: 'analytics', label: 'Store Analytics', icon: TrendingUp },
              { id: 'products', label: `Products (${sellerProducts.length})`, icon: Package },
              { id: 'orders', label: `Orders (${sellerOrders.length})`, icon: ShoppingBag },
              { id: 'wallet', label: 'Wallet & Payouts', icon: Wallet },
              { id: 'staff', label: 'Staff Roles', icon: Users },
              { id: 'settings', label: 'Store Settings', icon: Store }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as SellerTab)}
                className={`w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all ${
                  activeTab === tab.id
                    ? 'bg-primary text-gray-950 font-black shadow-glow'
                    : 'text-slate-400 hover:text-white hover:bg-white/5'
                }`}
              >
                <tab.icon className="w-4 h-4 shrink-0" />
                <span>{tab.label}</span>
              </button>
            ))}
          </nav>
        </div>

        {/* Footer Actions */}
        <div className="space-y-2 pt-6 border-t border-white/10">
          <Link
            href="/"
            className="flex items-center gap-2 text-xs text-slate-400 hover:text-white px-3 py-2 rounded-lg hover:bg-white/5 transition-colors"
          >
            <ArrowRight className="w-3.5 h-3.5 rotate-180" /> Back to Marketplace
          </Link>
          <button
            onClick={async () => {
              await logout();
              window.location.href = '/seller/login';
            }}
            className="w-full flex items-center gap-2 text-xs text-rose-400 hover:text-rose-300 px-3 py-2 rounded-lg hover:bg-rose-500/10 transition-colors cursor-pointer font-bold"
          >
            <LogOut className="w-3.5 h-3.5" /> Sign Out
          </button>
        </div>
      </aside>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 p-6 lg:p-8 overflow-y-auto space-y-6">
        {/* Top Header */}
        <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-white/10">
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight">
              {activeTab === 'analytics' && 'Store Performance & Analytics'}
              {activeTab === 'products' && 'Product Inventory Management'}
              {activeTab === 'orders' && 'Order Processing Queue'}
              {activeTab === 'wallet' && 'Seller Escrow Wallet'}
              {activeTab === 'staff' && 'Store Staff & Roles'}
              {activeTab === 'settings' && 'Store Configuration'}
            </h1>
            <p className="text-xs text-slate-400 mt-0.5">
